  protected get org(): HrmOrgNode { return this.txNode(this.orgRaw); }
  protected get matrix(): HrmOrgNode { return this.txNode(this.matrixRaw); }

  private findNode(id: string): HrmOrgNode | null {
    const dfs = (n: HrmOrgNode): HrmOrgNode | null => {
      if (n.id === id) return n;
      for (const c of n.children ?? []) { const r = dfs(c); if (r) return r; }
      return null;
    };
    return dfs(this.orgRaw);
  }
  private parentOf(id: string): HrmOrgNode | null {
    const dfs = (n: HrmOrgNode): HrmOrgNode | null => {
      for (const c of n.children ?? []) { if (c.id === id) return n; const r = dfs(c); if (r) return r; }
      return null;
    };
    return dfs(this.orgRaw);
  }
  protected selName(): string {
    if (!this.sel()) return '—';
    return this.findNode(this.sel())?.name ?? '—';
  }
  /** " · báo cáo cho: <quản lý>" — ai ở trên node đang chọn (tên người giữ nguyên). */
  protected selReport(): string {
    if (!this.sel()) return '';
    const p = this.parentOf(this.sel());
    return p ? ` · ${this.t.instant('docs.orgChart.selReportTo')}: ${p.name}` : ` · ${this.t.instant('docs.orgChart.selTop')}`;
  }
  protected modeName(): string {
    const m: Record<HrmOrgViewMode, string> = {
      employee: this.t.instant('docs.orgChart.lblModeEmployee'),
      position: this.t.instant('docs.orgChart.lblModePosition'),
      department: this.t.instant('docs.orgChart.lblModeDepartment'),
    };
    return m[this.mode()];
  }
